cd /private/var/folders/82/dclbn8z5181_3ppfdtp8csd40000gn/T/bench-scratch/6dfd85d5-014a-4b28-8372-5e549c5e4f2d; grep -n "export" tests/server/_support/fixtures.ts | head; cat > tests/zz-move-smoke.test.ts <<'EOF'
import { afterAll, beforeAll, expect, it, vi } from "vitest";
vi.mock("@/lib/id", () => import("./server/_support/doubles/id"));
import { subscribe } from "@/lib/event-bus";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import { registerActivityListeners, listActivity } from "@/server/services/activity-service";
import { createTenant, issueInput, useTemporaryDatabase } from "./server/_support/fixtures";
let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());
it("moves", async () => {
  const off = registerActivityListeners();
  const t = await createTenant("mv");
  const other = await projectService.createProject(t.actors.admin, { orgId: t.org.id, name: "Other", key: "OTH", slug: "other" } as never);
  const a = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { title: "one" }));
  const b = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { title: "two" }));
  const seen: unknown[] = [];
  const off2 = subscribe("issue.moved", (p) => { seen.push(p); });
  const moved = await issueService.moveIssueToProject(t.actors.member, { orgId: t.org.id, issueId: b.id, toProjectId: other.id });
  expect(moved.projectId).toBe(other.id); expect(moved.number).toBe(1);
  const c = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { title: "three" }));
  expect(c.number).toBe(3);
  const back = await issueService.moveIssueToProject(t.actors.member, { orgId: t.org.id, issueId: b.id, toProjectId: t.project.id });
  expect(back.number).toBe(4);
  const same = await issueService.moveIssueToProject(t.actors.member, { orgId: t.org.id, issueId: a.id, toProjectId: t.project.id });
  expect(same.number).toBe(1);
  expect(seen.length).toBe(2);
  const log = await listActivity(t.actors.owner, { orgId: t.org.id, action: ["issue.moved"], limit: 25, cursor: null } as never);
  console.log(JSON.stringify(log.items[0]), JSON.stringify(seen[0]));
  expect(await issueRepo.nextIssueNumber(t.org.id, other.id)).toBe(2);
  off(); off2();
});
EOF
